{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2188-05-26 14:40:00",
      "speaker": "Doctor",
      "text": "Hello, I’m Dr. Lee. I’ll be your doctor during this hospital stay. You came in with abdominal pain and nausea—can you tell me more about what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2188-05-26 14:41:00",
      "speaker": "Patient",
      "text": "Hi, yes. I’ve had this gnawing pain in my upper belly for a couple of days. It’s constant, and I keep dry heaving. I didn’t throw up anything real—just phlegm."
    },
    {
      "turn_number": 3,
      "time": "2188-05-26 14:42:00",
      "speaker": "Doctor",
      "text": "I see. Is the pain worse after eating? Does it radiate anywhere?"
    },
    {
      "turn_number": 4,
      "time": "2188-05-26 14:43:00",
      "speaker": "Patient",
      "text": "No, it doesn’t move. But it feels worse when I try to eat. I haven’t been able to keep much down."
    },
    {
      "turn_number": 5,
      "time": "2188-05-26 14:44:00",
      "speaker": "Doctor",
      "text": "That fits with your history of gastroparesis. We’ll treat this as a flare. We’ve started IV fluids, and you’re getting metoclopramide to help your stomach empty."
    },
    {
      "turn_number": 6,
      "time": "2188-05-26 14:45:00",
      "speaker": "Patient",
      "text": "Okay. I’ve been through this before. But it’s getting harder to manage at home."
    },
    {
      "turn_number": 7,
      "time": "2188-05-26 14:46:00",
      "speaker": "Doctor",
      "text": "I understand. We’ll make sure you’re stable before discharge. We also gave you IV morphine for pain and Ativan for nausea. How’s the pain now?"
    },
    {
      "turn_number": 8,
      "time": "2188-05-26 14:47:00",
      "speaker": "Patient",
      "text": "It’s better—maybe a 4 now. But I’m still nauseous."
    },
    {
      "turn_number": 9,
      "time": "2188-05-26 14:48:00",
      "speaker": "Doctor",
      "text": "We’ll keep the anti-nausea meds going. Your labs show low potassium, so we’re replacing that too. It’s common with vomiting."
    },
    {
      "turn_number": 10,
      "time": "2188-05-26 14:49:00",
      "speaker": "Patient",
      "text": "Oh, okay. I didn’t know that could happen."
    },
    {
      "turn_number": 11,
      "time": "2188-05-26 14:50:00",
      "speaker": "Doctor",
      "text": "Yes, and we want to avoid complications. No imaging today since your symptoms match your usual flares and there’s no sign of blockage."
    },
    {
      "turn_number": 12,
      "time": "2188-05-26 14:51:00",
      "speaker": "Patient",
      "text": "That’s good. I’ve had so many scans lately."
    },
    {
      "turn_number": 13,
      "time": "2188-05-27 08:30:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs improved overnight. Potassium is better, and your acidosis is resolving. We’ll keep you on IV meds a bit longer."
    },
    {
      "turn_number": 14,
      "time": "2188-05-27 08:31:00",
      "speaker": "Patient",
      "text": "That’s good. I feel a little less nauseous. Can I try sipping water?"
    },
    {
      "turn_number": 15,
      "time": "2188-05-27 08:32:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll start small. If you tolerate it, we’ll advance your diet slowly. We’re also switching back to your home omeprazole."
    },
    {
      "turn_number": 16,
      "time": "2188-05-27 08:33:00",
      "speaker": "Patient",
      "text": "I’ve been on that for years since my fundoplication."
    },
    {
      "turn_number": 17,
      "time": "2188-05-27 08:34:00",
      "speaker": "Doctor",
      "text": "Right. And we’re continuing your metoclopramide. How’s your pain?"
    },
    {
      "turn_number": 18,
      "time": "2188-05-27 08:35:00",
      "speaker": "Patient",
      "text": "Still there, but manageable. I’m on my regular morphine at home."
    },
    {
      "turn_number": 19,
      "time": "2188-05-27 08:36:00",
      "speaker": "Doctor",
      "text": "We’ll transition you back to that soon. But we need to talk about your pain meds—some, like tramadol and Dilaudid, can worsen gastroparesis."
    },
    {
      "turn_number": 20,
      "time": "2188-05-27 08:37:00",
      "speaker": "Patient",
      "text": "I didn’t know that. I only take Dilaudid when it’s really bad."
    },
    {
      "turn_number": 21,
      "time": "2188-05-27 08:38:00",
      "speaker": "Doctor",
      "text": "We recommend minimizing those. Work with your oncologist to adjust your morphine if needed. It’s a balance, but important for your stomach."
    },
    {
      "turn_number": 22,
      "time": "2188-05-27 08:39:00",
      "speaker": "Patient",
      "text": "Okay, I’ll bring it up at my next visit."
    },
    {
      "turn_number": 23,
      "time": "2188-05-28 09:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. You’ve kept down clear liquids and soft foods. We’re switching all your meds to oral form."
    },
    {
      "turn_number": 24,
      "time": "2188-05-28 09:01:00",
      "speaker": "Patient",
      "text": "That’s great. I’m feeling more like myself."
    },
    {
      "turn_number": 25,
      "time": "2188-05-28 09:02:00",
      "speaker": "Doctor",
      "text": "Your last labs look stable. Hemoglobin is low but unchanged, and liver enzymes are normal. Your cancer-related pain is under control?"
    },
    {
      "turn_number": 26,
      "time": "2188-05-28 09:03:00",
      "speaker": "Patient",
      "text": "Yes, gabapentin and morphine help. My back pain from the bone mets is stable."
    },
    {
      "turn_number": 27,
      "time": "2188-05-28 09:04:00",
      "speaker": "Doctor",
      "text": "Good. Your oncologist is aware you’re here. Taxol is on hold for now due to your frequent admissions."
    },
    {
      "turn_number": 28,
      "time": "2188-05-28 09:05:00",
      "speaker": "Patient",
      "text": "I’m tired of being in and out of the hospital."
    },
    {
      "turn_number": 29,
      "time": "2188-05-28 09:06:00",
      "speaker": "Doctor",
      "text": "We’re focusing on stabilizing your symptoms. You mentioned Tigan—why did you stop it?"
    },
    {
      "turn_number": 30,
      "time": "2188-05-28 09:07:00",
      "speaker": "Patient",
      "text": "I only tried it once. It didn’t help, so I didn’t keep using it."
    },
    {
      "turn_number": 31,
      "time": "2188-05-28 09:08:00",
      "speaker": "Doctor",
      "text": "Understood. We won’t restart it. We’ll stick with what works—metoclopramide and prochlorperazine as needed."
    },
    {
      "turn_number": 32,
      "time": "2188-05-28 09:09:00",
      "speaker": "Patient",
      "text": "And the Ativan helps with the nausea and anxiety."
    },
    {
      "turn_number": 33,
      "time": "2188-05-28 09:10:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll keep that available. Your heart condition is stable too—still on aspirin and Plavix after your PFO closure?"
    },
    {
      "turn_number": 34,
      "time": "2188-05-28 09:11:00",
      "speaker": "Patient",
      "text": "Yes, I haven’t missed a dose. That TIA scare was scary, but I’ve been okay since."
    },
    {
      "turn_number": 35,
      "time": "2188-05-28 09:12:00",
      "speaker": "Doctor",
      "text": "Good. No new neurological symptoms?"
    },
    {
      "turn_number": 36,
      "time": "2188-05-28 09:13:00",
      "speaker": "Patient",
      "text": "No, nothing since that one time."
    },
    {
      "turn_number": 37,
      "time": "2188-05-29 10:00:00",
      "speaker": "Doctor",
      "text": "You’ve done great. You’ve been on regular food, no vomiting, and your pain is controlled. We’re planning discharge tomorrow."
    },
    {
      "turn_number": 38,
      "time": "2188-05-29 10:01:00",
      "speaker": "Patient",
      "text": "That’s a relief. What should I watch for at home?"
    },
    {
      "turn_number": 39,
      "time": "2188-05-29 10:02:00",
      "speaker": "Doctor",
      "text": "If nausea returns or you can’t keep food down, come back. Also, avoid those pain meds we discussed. They can trigger flares."
    },
    {
      "turn_number": 40,
      "time": "2188-05-29 10:03:00",
      "speaker": "Patient",
      "text": "I’ll stick to my regular morphine and avoid the others."
    },
    {
      "turn_number": 41,
      "time": "2188-05-29 10:04:00",
      "speaker": "Doctor",
      "text": "Exactly. And keep your appointments—especially with your oncologist and for your Botox injections for gastroparesis."
    },
    {
      "turn_number": 42,
      "time": "2188-05-29 10:05:00",
      "speaker": "Patient",
      "text": "I have one scheduled next week."
    },
    {
      "turn_number": 43,
      "time": "2188-05-30 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re cleared for discharge. Your exam is soft, no tenderness, and bowel sounds are present."
    },
    {
      "turn_number": 44,
      "time": "2188-05-30 08:01:00",
      "speaker": "Patient",
      "text": "I feel ready. What meds am I going home with?"
    },
    {
      "turn_number": 45,
      "time": "2188-05-30 08:02:00",
      "speaker": "Doctor",
      "text": "All your usual ones—aspirin, Plavix, metoclopramide, morphine, gabapentin, omeprazole, and the rest. We’re keeping Tigan on the list, but only if you want to try it again."
    },
    {
      "turn_number": 46,
      "time": "2188-05-30 08:03:00",
      "speaker": "Patient",
      "text": "I’ll leave it for now. If things get bad, I’ll call my GI doctor."
    },
    {
      "turn_number": 47,
      "time": "2188-05-30 08:04:00",
      "speaker": "Doctor",
      "text": "Perfect. We’ll send instructions to your home. Focus on small, frequent meals and staying hydrated."
    },
    {
      "turn_number": 48,
      "time": "2188-05-30 08:05:00",
      "speaker": "Patient",
      "text": "And I’ll try to cut back on the strong painkillers."
    },
    {
      "turn_number": 49,
      "time": "2188-05-30 08:06:00",
      "speaker": "Doctor",
      "text": "That’s the plan. You’re doing well. We’re here if you need us."
    },
    {
      "turn_number": 50,
      "time": "2188-05-30 08:07:00",
      "speaker": "Patient",
      "text": "Thank you, Dr. Lee. I appreciate the care."
    },
    {
      "turn_number": 51,
      "time": "2188-05-30 08:08:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care, and we’ll see you in follow-up if needed."
    },
    {
      "turn_number": 52,
      "time": "2188-05-30 08:09:00",
      "speaker": "Patient",
      "text": "Will do."
    },
    {
      "turn_number": 53,
      "time": "2188-05-30 08:10:00",
      "speaker": "Doctor",
      "text": "Nurse will come by with your discharge papers and prescriptions shortly."
    },
    {
      "turn_number": 54,
      "time": "2188-05-30 08:11:00",
      "speaker": "Patient",
      "text": "Okay, thanks."
    },
    {
      "turn_number": 55,
      "time": "2188-05-30 08:12:00",
      "speaker": "Doctor",
      "text": "One last thing—your recent imaging showed improvement in bowel inflammation. That’s a good sign."
    },
    {
      "turn_number": 56,
      "time": "2188-05-30 08:13:00",
      "speaker": "Patient",
      "text": "That’s good to hear. I was worried it might be something else."
    },
    {
      "turn_number": 57,
      "time": "2188-05-30 08:14:00",
      "speaker": "Doctor",
      "text": "No signs of obstruction or diverticulitis. This was a gastroparesis flare, and we’ve managed it well."
    },
    {
      "turn_number": 58,
      "time": "2188-05-30 08:15:00",
      "speaker": "Patient",
      "text": "I’m glad it’s under control for now."
    },
    {
      "turn_number": 59,
      "time": "2188-05-30 08:16:00",
      "speaker": "Doctor",
      "text": "We’ll keep monitoring. Call your team if symptoms return."
    },
    {
      "turn_number": 60,
      "time": "2188-05-30 08:17:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 61,
      "time": "2188-05-30 08:18:00",
      "speaker": "Doctor",
      "text": "You’re doing great. Take it easy at home."
    },
    {
      "turn_number": 62,
      "time": "2188-05-30 08:19:00",
      "speaker": "Patient",
      "text": "I plan to rest and take it slow."
    },
    {
      "turn_number": 63,
      "time": "2188-05-30 08:20:00",
      "speaker": "Doctor",
      "text": "Perfect. We’ll follow up with your primary team."
    },
    {
      "turn_number": 64,
      "time": "2188-05-30 08:21:00",
      "speaker": "Patient",
      "text": "Okay, I’ll keep my appointments."
    },
    {
      "turn_number": 65,
      "time": "2188-05-30 08:22:00",
      "speaker": "Doctor",
      "text": "Great. Take care."
    },
    {
      "turn_number": 66,
      "time": "2188-05-30 08:23:00",
      "speaker": "Patient",
      "text": "Thank you."
    },
    {
      "turn_number": 67,
      "time": "2188-05-30 08:24:00",
      "speaker": "Doctor",
      "text": "See you soon."
    }
  ],
  "summary": {
    "admission_start": "2188-05-26 14:40:00",
    "admission_end": "2188-05-30 15:00:00",
    "summary_paragraph": "A woman with metastatic breast cancer and a history of gastroparesis was admitted for recurrent nausea, vomiting, and abdominal pain consistent with a gastroparesis flare. She had been recently treated for similar symptoms and had a complex medical history including PFO closure and TIA. Her symptoms improved with IV fluids, antiemetics, and pain management. She was transitioned to oral medications, tolerated a regular diet, and was discharged home in stable condition. The care team emphasized minimizing opioid use that could worsen gastroparesis and continuing follow-up with her oncologist and GI specialist.",
    "problems": [
      "Gastroparesis",
      "Secondary malignant neoplasm of bone",
      "Acidosis",
      "Malignant neoplasm of unspecified site of left female breast",
      "Gastro-esophageal reflux disease without esophagitis",
      "Estrogen receptor positive status [ER+]",
      "Neoplasm related pain (acute) (chronic)",
      "Secondary malignant neoplasm of liver and intrahepatic bile duct",
      "Personal history of transient ischemic attack (TIA), and cerebral infarction without residual deficits",
      "Hypothyroidism, unspecified",
      "Hypokalemia",
      "Major depressive disorder, single episode, unspecified",
      "Anxiety disorder, unspecified",
      "Diverticulosis of intestine, part unspecified, without perforation or abscess without bleeding",
      "Personal history of malignant neoplasm of breast",
      "Dehydration"
    ]
  }
}
